// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: POC (branch poc-omarchy): the app's panels tiled the way Hyprland's dwindle layout tiles
//          windows, with Omarchy's animation timings. The server still says which panels are wanted
//          (data-shown on each .tile, data-zoomed on .tiles); this only decides where they go and how
//          they move. A new panel splits the panel you were in (side by side when it is wide, stacked
//          when tall); a closed one gives its space to its sibling. Drag the line between two to resize.
//          Values from ~/.local/share/omarchy/default/hypr/looknfeel.lua (gaps 0 and no border: the
//          user's own setup); the arrangement is kept in localStorage ("delulu.tiles").
// ---------------------------------------------------------------------------
(() => {
  const PANES = ["chat", "results", "python", "variables", "terminal"];
  const STORE = "delulu.tiles";
  const LINE = 1;  // gaps_in 0, border 0: just the one dividing line the panels already had
  const GRAB = 8;  // extend_border_grab_area
  // Hyprland speeds are in ds (100 ms); curves are its bezier points
  const EASE_OUT_QUINT = "cubic-bezier(0.23, 1, 0.32, 1)";
  const ALMOST_LINEAR = "cubic-bezier(0.5, 0.5, 0.75, 1)";
  const MOVE = { duration: 379, easing: EASE_OUT_QUINT };   // windows
  const POP_IN = { duration: 410, easing: EASE_OUT_QUINT };  // windowsIn, popin 87%
  const FADE_IN = { duration: 173, easing: ALMOST_LINEAR };  // fadeIn
  const POP_OUT = { duration: 149, easing: "linear" };       // windowsOut, popin 87%
  const POP = 0.87;

  let root = null;
  let tree = load();
  let focused = "chat";
  let nodes = [];      // the split nodes, in the order of their drag handles
  let size = "";       // the container's size at the last layout
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;

  // --- the tree: a leaf {pane} or a split {a, b, ratio}; a's share is ratio -----------------
  function load() {
    try { return JSON.parse(localStorage.getItem(STORE)) || null; } catch { return null; }
  }
  const save = () => localStorage.setItem(STORE, JSON.stringify(tree, (k, v) => (k === "rect" ? undefined : v)));
  const leaves = (node) => (!node ? [] : node.pane ? [node.pane] : [...leaves(node.a), ...leaves(node.b)]);
  function remove(node, pane) {
    if (!node || node.pane === pane) return null;
    if (node.pane) return node;
    const a = remove(node.a, pane);
    const b = remove(node.b, pane);
    return !a ? b : !b ? a : { ...node, a, b };  // the sibling takes the parent's place
  }
  function insert(node, at, pane) {
    if (!node) return { pane };
    if (node.pane) return node.pane === at ? { a: node, b: { pane }, ratio: 0.5 } : node;
    return { ...node, a: insert(node.a, at, pane), b: insert(node.b, at, pane) };
  }

  // --- layout: the rect of every leaf, and of every split (for its handle) ---------------------
  function layout(node, x, y, w, h, out) {
    if (!node) return;
    if (node.pane) { out[node.pane] = { x, y, w, h }; return; }
    // as dwindle with preserve_split off: side by side when wider than tall, else stacked
    const side = w > h;
    node.rect = { x, y, w, h, side };
    nodes.push(node);
    if (side) {
      const aw = Math.round((w - LINE) * node.ratio);
      layout(node.a, x, y, aw, h, out);
      layout(node.b, x + aw + LINE, y, w - aw - LINE, h, out);
    } else {
      const ah = Math.round((h - LINE) * node.ratio);
      layout(node.a, x, y, w, ah, out);
      layout(node.b, x, y + ah + LINE, w, h - ah - LINE, out);
    }
  }

  const tile = (pane) => root.querySelector(`:scope > .tile[data-pane="${pane}"]`);
  const isOn = (el) => el && el.dataset.tile === "on";
  function place(el, r, z) {
    Object.assign(el.style, { left: `${r.x}px`, top: `${r.y}px`, width: `${r.w}px`, height: `${r.h}px`, zIndex: z });
    el.dataset.tile = "on";
  }
  // where a tile is on screen now (mid-animation too), relative to the container
  function seen(el) {
    const box = el.getBoundingClientRect();
    const at = root.getBoundingClientRect();
    return { x: box.left - at.left, y: box.top - at.top, w: box.width, h: box.height };
  }
  const later = (el, ms, fn) => { clearTimeout(el._tileTimer); el._tileTimer = setTimeout(fn, ms); };

  // --- sync: the wanted panels -> tree -> rects -> animate from where they were ---------------
  function sync(animate) {
    if (!root || !root.isConnected) return;
    const shown = PANES.filter((pane) => tile(pane)?.dataset.shown === "true");
    const zoomed = root.dataset.zoomed || "";
    const before = {};
    for (const pane of PANES) {
      const el = tile(pane);
      if (!el) continue;
      if (isOn(el)) before[pane] = seen(el);
      el.getAnimations().forEach((anim) => anim.cancel());
      clearTimeout(el._tileTimer);
    }

    for (const pane of leaves(tree)) if (!shown.includes(pane) || !tile(pane)) tree = remove(tree, pane);
    for (const pane of shown) {
      const have = leaves(tree);
      if (have.includes(pane)) continue;
      // dwindle: the new window splits the focused one, and is focused next
      tree = insert(tree, have.includes(focused) ? focused : have[have.length - 1], pane);
      focused = pane;
    }
    save();

    const W = root.clientWidth;
    const H = root.clientHeight;
    size = `${W}x${H}`;
    nodes = [];
    const rects = {};
    layout(tree, 0, 0, W, H, rects);
    if (zoomed) rects[zoomed] = { x: 0, y: 0, w: W, h: H };
    const after = zoomed ? [zoomed] : shown;

    for (const pane of PANES) {
      const el = tile(pane);
      if (!el) continue;
      const was = before[pane];
      const r = rects[pane];
      if (after.includes(pane)) {
        place(el, r, pane === zoomed ? 3 : 1);
        if (!animate || reduced) continue;
        if (!was) {
          el.animate([{ transform: `scale(${POP})`, transformOrigin: "50% 50%" }, { transform: "none", transformOrigin: "50% 50%" }], POP_IN);
          el.animate([{ opacity: 0 }, { opacity: 1 }], FADE_IN);
        } else if (Math.abs(was.x - r.x) + Math.abs(was.y - r.y) + Math.abs(was.w - r.w) + Math.abs(was.h - r.h) > 1) {
          // FLIP: jump to the new rect, then play back from the old one (stretched, as Hyprland does)
          const from = `translate(${was.x - r.x}px, ${was.y - r.y}px) scale(${was.w / r.w}, ${was.h / r.h})`;
          el.animate([{ transform: from }, { transform: "none" }], MOVE);
        }
      } else if (was && zoomed && shown.includes(pane)) {
        // under the panel filling the window: stays put until covered, then out of the way
        el.style.zIndex = 0;
        later(el, animate ? MOVE.duration : 0, () => { el.dataset.tile = "gone"; });
      } else if (was && animate && !reduced) {
        el.style.zIndex = 2;  // closing on top, while its neighbours grow under it
        const out = el.animate(
          [
            { transform: "none", opacity: 1, transformOrigin: "50% 50%" },
            { transform: `scale(${POP})`, opacity: 0, transformOrigin: "50% 50%" },
          ],
          { ...POP_OUT, fill: "forwards" },
        );
        out.onfinish = () => { el.dataset.tile = "gone"; out.cancel(); };
      } else {
        el.dataset.tile = "gone";
      }
    }
    handles(zoomed);
    // grids, editors and the terminal size themselves on resize, once things have landed
    later(root, animate ? POP_IN.duration + 20 : 0, () => window.dispatchEvent(new Event("resize")));
  }

  // --- drag handles on the line of each split (resize_on_border) -------------------------------
  function handles(zoomed) {
    const box = root.querySelector(":scope > .tile-splits");
    if (!box) return;
    const list = zoomed ? [] : nodes;
    while (box.children.length > list.length) box.lastChild.remove();
    while (box.children.length < list.length) {
      const handle = document.createElement("div");
      handle.className = "tile-split";
      handle.addEventListener("pointerdown", drag);
      box.append(handle);
    }
    list.forEach((node, i) => {
      const r = node.rect;
      const handle = box.children[i];
      handle.dataset.node = i;
      handle.classList.toggle("is-side", r.side);
      const at = r.side ? r.x + Math.round((r.w - LINE) * node.ratio) : r.y + Math.round((r.h - LINE) * node.ratio);
      Object.assign(handle.style, r.side
        ? { left: `${at - GRAB / 2}px`, top: `${r.y}px`, width: `${GRAB + LINE}px`, height: `${r.h}px` }
        : { left: `${r.x}px`, top: `${at - GRAB / 2}px`, width: `${r.w}px`, height: `${GRAB + LINE}px` });
    });
  }

  function drag(event) {
    const handle = event.currentTarget;
    const node = nodes[Number(handle.dataset.node)];
    if (!node) return;
    event.preventDefault();
    handle.setPointerCapture(event.pointerId);
    root.classList.add("is-dragging");  // iframes (the Terminal) would swallow the moves
    const move = (e) => {
      const at = root.getBoundingClientRect();
      const r = node.rect;
      const ratio = r.side ? (e.clientX - at.left - r.x) / r.w : (e.clientY - at.top - r.y) / r.h;
      node.ratio = Math.min(0.9, Math.max(0.1, ratio));
      sync(false);
    };
    const up = () => {
      handle.removeEventListener("pointermove", move);
      root.classList.remove("is-dragging");
      save();
    };
    handle.addEventListener("pointermove", move);
    handle.addEventListener("pointerup", up, { once: true });
    handle.addEventListener("pointercancel", up, { once: true });
  }

  // --- which panel you are in: where the next one splits from ----------------------------------
  const track = (event) => {
    const pane = event.target instanceof Element && event.target.closest(".tiles > .tile[data-pane]");
    if (pane) focused = pane.dataset.pane;
  };
  document.addEventListener("focusin", track, true);
  document.addEventListener("pointerdown", track, true);

  window.addEventListener("resize", () => {
    if (root && `${root.clientWidth}x${root.clientHeight}` !== size) sync(false);
  });

  // React draws the page after this script runs: wait for the container, then follow its changes
  (function start() {
    root = document.querySelector(".tiles");
    if (!root) return requestAnimationFrame(start);
    sync(false);
    new MutationObserver(() => sync(true)).observe(root, {
      attributes: true, subtree: true, attributeFilter: ["data-shown", "data-zoomed"],
    });
  })();
})();
